import http from 'node:http';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, join, extname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(root, 'workboard.sqlite');
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);`);
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
db.exec('PRAGMA foreign_keys = ON');
const port = Number(process.env.PORT || 8080);
const mime = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8' };
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  const send = (status, body, type = 'application/json; charset=utf-8') => { res.writeHead(status, { 'content-type': type, 'x-content-type-options': 'nosniff' }); res.end(typeof body === 'string' || Buffer.isBuffer(body) ? body : JSON.stringify(body)); };
  const readBody = async () => { let raw = ''; for await (const chunk of req) { raw += chunk; if (raw.length > 10000) throw new Error('Body too large'); } return JSON.parse(raw); };
  if (req.method === 'GET' && url.pathname === '/health') return send(200, { status: 'ok' });
  if (url.pathname === '/api/projects' && req.method === 'GET') return send(200, db.prepare('SELECT p.id, p.name, p.archived, COUNT(t.id) AS total_count, COALESCE(SUM(t.completed), 0) AS completed_count FROM projects p LEFT JOIN tasks t ON t.project_id=p.id GROUP BY p.id ORDER BY p.id').all().map(project => ({ ...project, archived: Boolean(project.archived) })));
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    try { const data = await readBody(); if (typeof data.name !== 'string' || !data.name.trim()) return send(400, { error: 'Project name is required' }); const name = data.name.trim(); const result = db.prepare('INSERT INTO projects(name) VALUES (?)').run(name); return send(201, { id: Number(result.lastInsertRowid), name }); } catch { return send(400, { error: 'Invalid request' }); }
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    const project = db.prepare('SELECT id, archived FROM projects WHERE id=?').get(projectId);
    if (!project) return send(404, { error: 'Project not found' });
    if (req.method === 'GET') return send(200, db.prepare('SELECT id, title, completed FROM tasks WHERE project_id=? ORDER BY id').all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) })));
    if (req.method === 'POST') {
      if (project.archived) return send(409, { error: 'Archived project' });
      try { const data = await readBody(); if (typeof data.title !== 'string' || !data.title.trim()) return send(400, { error: 'Task title is required' }); const title = data.title.trim(); const result = db.prepare('INSERT INTO tasks(project_id,title) VALUES (?,?)').run(projectId, title); return send(201, { id: Number(result.lastInsertRowid), title, completed: false }); } catch { return send(400, { error: 'Invalid request' }); }
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/tasks\/(\d+)$/);
  if (req.method === 'PATCH' && taskMatch) {
    try { const data = await readBody(); if (typeof data.completed !== 'boolean') return send(400, { error: 'Invalid completion state' }); const result = db.prepare('UPDATE tasks SET completed=? WHERE id=? AND project_id IN (SELECT id FROM projects WHERE archived=0)').run(data.completed ? 1 : 0, Number(taskMatch[1])); return result.changes ? send(200, { completed: data.completed }) : send(404, { error: 'Task not found' }); } catch { return send(400, { error: 'Invalid request' }); }
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (req.method === 'POST' && archiveMatch) {
    const result = db.prepare('UPDATE projects SET archived=? WHERE id=?').run(archiveMatch[2] === 'archive' ? 1 : 0, Number(archiveMatch[1]));
    return result.changes ? send(200, { status: 'ok' }) : send(404, { error: 'Project not found' });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (req.method === 'GET' && projectMatch) { const project = db.prepare('SELECT id, name, archived FROM projects WHERE id=?').get(Number(projectMatch[1])); return project ? send(200, { ...project, archived: Boolean(project.archived) }) : send(404, { error: 'Project not found' }); }
  if (req.method === 'GET') {
    const file = url.pathname === '/' || /^\/projects\/\d+\/?$/.test(url.pathname) ? 'index.html' : url.pathname.slice(1);
    if (file.includes('..') || file.includes('\\')) return send(404, 'Not found', 'text/plain');
    try { return send(200, readFileSync(join(root, 'public', file)), mime[extname(file)] || 'application/octet-stream'); } catch { return send(404, 'Not found', 'text/plain; charset=utf-8'); }
  }
  send(404, { error: 'Not found' });
});
server.listen(port, '0.0.0.0');

const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const alert = document.querySelector('#alert');
let activeProjectId = null;

async function loadProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  const projects = await response.json();
  const filter = document.querySelector('#project-filter').value;
  const container = document.querySelector('#projects');
  container.replaceChildren();
  for (const project of projects.filter(item => item.archived === (filter === 'Archived'))) {
    const row = document.createElement('div'); row.dataset.testid = 'project-row'; row.className = 'project-row';
    const name = document.createElement('span'); name.textContent = project.name;
    const button = document.createElement('button'); button.type = 'button'; button.textContent = 'Open project';
    button.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
    const summary = document.createElement('span'); summary.dataset.testid = 'project-summary'; summary.textContent = `${project.completed_count}/${project.total_count} completed`;
    row.append(name, summary, button);
    const stateButton = document.createElement('button'); stateButton.type = 'button'; stateButton.textContent = project.archived ? 'Restore project' : 'Archive project';
    stateButton.addEventListener('click', async () => { const action = project.archived ? 'restore' : 'archive'; const result = await fetch(`/api/projects/${project.id}/${action}`, { method: 'POST' }); if (result.ok) await loadProjects(); });
    row.append(stateButton); container.append(row);
  }
}

async function loadTasks() {
  const response = await fetch(`/api/projects/${activeProjectId}/tasks`);
  if (!response.ok) throw new Error('Could not load tasks');
  const tasks = await response.json();
  const filter = document.querySelector('#task-filter').value;
  const shown = tasks.filter(task => filter === 'All' || (filter === 'Completed') === task.completed);
  const container = document.querySelector('#tasks'); container.replaceChildren();
  for (const task of shown) {
    const row = document.createElement('div'); row.dataset.testid = 'task-row'; row.className = 'project-row';
    const title = document.createElement('span'); title.textContent = task.title;
    const checkbox = document.createElement('input'); checkbox.type = 'checkbox'; checkbox.checked = task.completed; checkbox.disabled = Boolean(window.currentProjectArchived); checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      const result = await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
      if (result.ok) await loadTasks(); else checkbox.checked = task.completed;
    });
    row.append(title, checkbox); container.append(row);
  }
}

async function showPage() {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (!match) { detailView.hidden = true; listView.hidden = false; await loadProjects(); return; }
  activeProjectId = match[1]; listView.hidden = true; detailView.hidden = false;
  const response = await fetch(`/api/projects/${activeProjectId}`);
  if (!response.ok) { document.querySelector('#project-title').textContent = 'Project not found'; return; }
  const project = await response.json(); window.currentProjectArchived = project.archived;
  document.querySelector('#project-title').textContent = project.name;
  document.querySelector('#archived-notice').hidden = !project.archived;
  document.querySelector('#task-title').disabled = project.archived;
  document.querySelector('#task-form button').disabled = project.archived;
  await loadTasks();
}

document.querySelector('#create-form').addEventListener('submit', async event => {
  event.preventDefault(); const input = document.querySelector('#project-name'); const name = input.value.trim();
  if (!name) { alert.textContent = 'Project name is required'; alert.hidden = false; return; }
  const response = await fetch('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
  if (!response.ok) { alert.textContent = 'Project name is required'; alert.hidden = false; return; }
  input.value = ''; alert.hidden = true; await loadProjects();
});

document.querySelector('#task-form').addEventListener('submit', async event => {
  event.preventDefault(); const input = document.querySelector('#task-title'); const title = input.value.trim(); const message = document.querySelector('#task-alert');
  if (!title) { message.textContent = 'Task title is required'; message.hidden = false; return; }
  const response = await fetch(`/api/projects/${activeProjectId}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
  if (!response.ok) { message.textContent = 'Task title is required'; message.hidden = false; return; }
  input.value = ''; message.hidden = true; await loadTasks();
});
document.querySelector('#task-filter').addEventListener('change', loadTasks);
document.querySelector('#project-filter').addEventListener('change', loadProjects);
document.querySelector('#back-button').addEventListener('click', () => { location.href = '/'; });
showPage().catch(() => { alert.textContent = 'Unable to load Workboard'; alert.hidden = false; listView.hidden = false; });

